// O no do agente devolve apenas 'output', por isso recuperamos o cliente
// correspondente pelo indice do item, que o agente preserva.
const base = $('Mensagem por template').all();

return $input.all().map((item, i) => {
  const original = base[i].json;
  const { mensagem_template, usar_ia, ...resto } = original;
  const texto = String(item.json.output ?? '').trim();
  const falhou = texto === '';

  return {
    json: {
      ...resto,
      mensagem: falhou ? mensagem_template : texto,
      origem: falhou ? 'template (fallback: a IA não respondeu)' : 'ia',
    },
  };
});

return $input.all().map((item) => {
  const { mensagem_template, usar_ia, ...resto } = item.json;
  return { json: { ...resto, mensagem: mensagem_template, origem: 'template' } };
});

// Monta o corpo HTML do email. Fica num no de Code em vez de numa expressao gigante
// dentro do no do Gmail: assim o HTML e legivel, versionavel e testavel a parte.
//
// Layout em tabelas e estilos em linha de proposito. Os clientes de email descartam
// <style> no <head> e nao suportam flexbox nem grid: o que funciona em todos e o que
// funcionava em 2005.

const escapar = (valor) => String(valor ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const emReais = (valor) => 'R$ ' + Number(valor).toLocaleString('pt-BR');

return $input.all().map((item) => {
  const c = item.json;
  const primeiroNome = escapar(c.nome.split(' ')[0]);

  // A mensagem vem do modelo ou do template, sempre como texto. Qualquer coisa que
  // venha de um LLM e tratada como dados, nunca como marcacao: daqui para a frente
  // vai escapada.
  const paragrafos = String(c.mensagem ?? '')
    .split(/\n{2,}/)
    .map((bloco) => bloco.trim())
    .filter((bloco) => bloco !== '')
    .map((bloco) => `<p style="margin:0 0 16px;font-size:15px;line-height:1.65;color:#2b2f36;">`
      + escapar(bloco).replace(/\n/g, '<br>')
      + `</p>`)
    .join('');

  const faixaDemo = c.modo === 'demo'
    ? `<tr><td style="background:#fff4d6;border-bottom:1px solid #f0dca8;padding:12px 28px;font-size:12px;color:#6b5420;">`
      + `<strong>Modo demonstracao.</strong> Destinatario original: `
      + `${escapar(c.nome)} &lt;${escapar(c.email)}&gt;`
      + `</td></tr>`
    : '';

  const linha = (rotulo, valor) => `<tr>`
    + `<td style="padding:9px 0;font-size:13px;color:#6a7280;border-bottom:1px solid #eceef1;width:42%;">${rotulo}</td>`
    + `<td style="padding:9px 0;font-size:13px;color:#2b2f36;border-bottom:1px solid #eceef1;font-weight:600;">${valor}</td>`
    + `</tr>`;

  const linhaAlternativas = (c.alternativas && c.alternativas.length > 0)
    ? linha('Tambem acessiveis ao seu saldo', escapar(c.alternativas.join(', ')))
    : '';

  const html = `<!doctype html>
<html lang="pt-br">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sua recomendacao de investimento</title>
</head>
<body style="margin:0;padding:0;background:#f4f6f8;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f6f8;padding:24px 12px;">
<tr><td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:10px;overflow:hidden;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;">

${faixaDemo}

<tr><td style="background:#1d3f6e;padding:26px 28px;">
<div style="font-size:11px;letter-spacing:1.4px;text-transform:uppercase;color:#9fc0ea;">Assistente de investimentos</div>
<div style="font-size:21px;font-weight:700;color:#ffffff;padding-top:6px;">Sua recomendacao, ${primeiroNome}</div>
</td></tr>

<tr><td style="padding:28px 28px 8px;">
${paragrafos}
</td></tr>

<tr><td style="padding:0 28px 8px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #eceef1;">
${linha('Perfil de investidor', escapar(c.perfil))}
${linha('Saldo disponivel', escapar(c.saldo_texto))}
${linha('Produto recomendado', escapar(c.produto_recomendado))}
${linha('Rentabilidade', escapar(c.rentabilidade))}
${linha('Aplicacao minima', emReais(c.minimo))}
${linhaAlternativas}
</table>
</td></tr>

<tr><td style="padding:20px 28px 28px;">
<div style="background:#f7f9fb;border-left:3px solid #c9d4e2;padding:12px 14px;font-size:12px;line-height:1.6;color:#5c6572;">
Esta mensagem foi gerada automaticamente a partir do seu perfil e do seu saldo.
Rentabilidade passada nao garante rentabilidade futura. Avalie as condicoes do
produto antes de investir.
</div>
</td></tr>

</table>
</td></tr>
</table>
</body>
</html>`;

  return { json: { ...c, email_html: html } };
});

// Um alerta com a lista toda, em vez de um ping por cliente. Dez notificacoes
// seguidas no telefone sao ruido; uma com dez linhas e informacao.
const falhas = $input.all().map((i) => i.json);
const linhas = falhas
  .map((f) => `- ${f.nome} <${f.email}>\n  ${f.erro_validacao}`)
  .join('\n');

const texto = [
  `Assistente de investimentos: ${falhas.length} email(s) nao enviado(s)`,
  ``,
  `Modo: ${falhas[0]?.modo ?? 'desconhecido'}`,
  `Momento: ${new Date().toISOString()}`,
  ``,
  linhas,
].join('\n');

return [{ json: { texto, total: falhas.length } }];
